head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05008";
scwin.rownum = 1;
scwin.result = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — gubun

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_fstSplitRedmptDd();
        scwin.init_datefmt_cal_intPayDd1();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05008.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "cal_intPayDd1", fn: function () { return String(String((dma_pageContext.get("intPayDd1") ?? ""))); } },
        { childId: "ipt_redmptAmt1", fn: function () { return String(String((dma_pageContext.get("redmptAmt1") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_fstSplitRedmptDd
 * @description 초기화 — datefmt cal fst Split Redmpt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_fstSplitRedmptDd = function () { $c.date.checkCalendarFormat("cal_fstSplitRedmptDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_intPayDd1
 * @description 초기화 — datefmt cal int Pay Dd1
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_intPayDd1 = function () { $c.date.checkCalendarFormat("cal_intPayDd1", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.makeInputFromParent($, {  });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05008.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_equivRedmptVal_onkeyup
 * @description ipt_equivRedmptVal 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_equivRedmptVal_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.util.getComponent('txt_equivRedmptValHanview').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05008.ipt_equivRedmptVal_onkeyup' }); }
};

