 */
scwin.btn_divSendForm_onclick = async function(e){
    try {
        await scwin.div_send_form((String(((dma_pageContext.get("gubun") ?? "")) == null ? '' : ((dma_pageContext.get("gubun") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("gubun") ?? "")) == null ? '' : ((dma_pageContext.get("gubun") ?? "")))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05008.btn_divSendForm_onclick' }); }
};

