///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_autoCalc
 * @description auto Calc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_autoCalc = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/split_redmpt_data.jsp"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/split_redmpt_data.jsp", unresolved: "action:../ajax/split_redmpt_data.jsp" };
};

/**
 * @method
 * @name NumberCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.NumberCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^0-9]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name cal_offMask
 * @description cal off Mask 처리
 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name chkDate
 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    $c.util.getComponent("ipt_equivRedmptVal").setValue(parentfm.equiv_redmpt_val.value);
    $c.util.getComponent("ipt_defrMms").setValue(parentfm.defr_mms.value);
    $c.util.getComponent("slc_redmptPdIntTpCd").setValue(parentfm.redmpt_pd_int_tp_cd.value);
    $c.util.getComponent("ipt_splitRedmptCnt").setValue(parentfm.split_redmpt_cnt.value);
    $c.util.getComponent("cal_fstSplitRedmptDd").setValue(parentfm.fst_split_redmpt_dd.value);
    $c.util.getComponent("ipt_splitRedmptCycle").setValue(parentfm.split_redmpt_cycle.value);
    const v_str = parentfm.split_redmpt_mmend_tp_cd.value;
    if (v_str === '1') {
        /* 수동 전환 필요: split_redmpt_mmend_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
    } else {
        if (v_str === '2') {
            /* 수동 전환 필요: split_redmpt_mmend_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
        }
    }
    $("input[name='equiv_redmpt_val']").trigger('onkeyup');
    $("input[name='equiv_redmpt_val']").trigger('onfocus');
    if (parentfm.non_eq_count.value === '') {
        scwin.rownum = 0;
    } else {
        scwin.rownum = parseInt(parentfm.non_eq_count.value);
    }
    let temprow = 0;
    if (scwin.rownum > 0) {
        temprow = scwin.rownum;
        $("#tbl_non_eq tr").remove();
        scwin.rownum = 0;
        for (let i = 1; i < temprow + 1; i++) {
            scwin.addRow();
            if (temprow === 1) {
                $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd.value"));
                $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt.value"));
            } else {
                if (temprow > 1) {
                    $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt[" + (i - 1) + "].value"));
                }
            }
        }
    } else {
        scwin.rownum = 1;
    }
};

/**
 * @method
 * @name data_Chk
 * @description data Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.data_Chk = async function () {
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_equivRedmptVal').getValue()) === 0) {
        await $c.win.alert("균등상환액을 입력하십시오.");
        $c.util.getComponent("ipt_equivRedmptVal").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_defrMms').getValue()) === 0) {
        await $c.win.alert("거치기간을 입력하십시오.");
        $c.util.getComponent("ipt_defrMms").focus();
        return false;
    }
    if ($c.util.getComponent('slc_redmptPdIntTpCd').getValue() === '') {
        await $c.win.alert("거치기간이자를 선택하십시오.");
        $c.util.getComponent("slc_redmptPdIntTpCd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCnt').getValue()) === 0) {
        await $c.win.alert("분할상환횟수를 입력하십시오.");
        $c.util.getComponent("ipt_splitRedmptCnt").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_fstSplitRedmptDd').getValue()) === 0) {
        await $c.win.alert("최초분할상환일을 입력하십시오.");
        $c.util.getComponent("cal_fstSplitRedmptDd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCycle').getValue()) === 0) {
        await $c.win.alert("상환주기를 입력하십시오.");
        $c.util.getComponent("ipt_splitRedmptCycle").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name div_send_form
 * @description div send form 처리
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.div_send_form = async function (index) {

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    if (!await scwin.data_Chk()) {
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_intPayDd1').getValue()) === 0) {
        await $c.win.alert("1차 분할상환일을 입력하십시오.");
        $c.util.getComponent("cal_intPayDd1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_redmptAmt1').getValue()) === 0) {
        await $c.win.alert("1차 상환금액을 입력하십시오.");
        $c.util.getComponent("ipt_redmptAmt1").focus();
        return;
    }
    const msg_str = "'분할상환일'을 입력하실경우 \n\r해당차수의 '상환금액'을 입력하세요. ";
    const msg_str1 = "해당차수의 '분할상환일'을 입력하세요. ";
    k = 7;
    for (i = 1; i <= scwin.rownum; i++) {
        if ($c.str.getByteLength(fm.elements[k].value) > 0) {
            if (($c.str.getByteLength(fm.elements[k+1].value) === 0)) {
                await $c.win.alert(msg_str);
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        } else {
            if (($c.str.getByteLength(fm.elements[k+1].value) > 0)) {
                await $c.win.alert(msg_str1);
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        k = k + 2;
    }
    $("#tbl_non_eq tr", ((scwin.openerScwin())["document"] !== undefined ? (scwin.openerScwin())["document"] : undefined)).remove();
    $("input[name=non_eq_count]", ((scwin.openerScwin())["document"] !== undefined ? (scwin.openerScwin())["document"] : undefined)).val(scwin.rownum);
    let tr;
    let td;

    const arrRows = [];
    for (let i = 1; i < scwin.rownum + 1; i++) {
        arrRows.push({ arrIntPaySeq: i, arrIntPayDd: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('intPayDd' + i))), arrRedmptAmt: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('redmptAmt' + i))) });
    }
    /* TODO Stage2: [sdd] 배열 파라미터 표현 미정(전환 미완) — 부모창 «tbl_non_eq» 로 보내던 키 [arrIntPaySeq, arrIntPayDd, arrRedmptAmt] · 행  arrRows.length 건 */
    await $c.win.alert('이 값을 부모 화면으로 보내는 방식을 아직 정하지 못했습니다(전환 미완) — 배열 파라미터 표현');

    parentfm.split_redmpt_tp_cd.value = index;
    $c.util.getComponent("ipt_equivRedmptVal").setValue($c.util.getComponent('ipt_equivRedmptVal').getValue());
    $c.util.getComponent("ipt_defrMms").setValue($c.util.getComponent('ipt_defrMms').getValue());
    $c.util.getComponent("slc_redmptPdIntTpCd").setValue($c.util.getComponent('slc_redmptPdIntTpCd').getValue());
    $c.util.getComponent("ipt_splitRedmptCnt").setValue($c.util.getComponent('ipt_splitRedmptCnt').getValue());
    $c.util.getComponent("cal_fstSplitRedmptDd").setValue($c.util.getComponent('cal_fstSplitRedmptDd').getValue());
    $c.util.getComponent("ipt_splitRedmptCycle").setValue($c.util.getComponent('ipt_splitRedmptCycle').getValue());
    if (($c.util.getComponent('ipt_splitRedmptMmendTpCd').getValue() !== '')) {
        $c.util.getComponent("ipt_splitRedmptMmendTpCd").setValue('1');
    } else {
        if (($c.util.getComponent('ipt_splitRedmptMmendTpCd_2').getValue() !== '')) {
            $c.util.getComponent("ipt_splitRedmptMmendTpCd").setValue('2');
        }
    }
    parentfm.eq_save_yn.value = "Y";
    if (parentfm.redmpt_methd_tp_cd[0].checked) {
        parentfm.redmpt_methd_tp_cd[0].checked = false;
    }
    parent.$c.win.closePopup();
};

/**
 * @method
 * @name div_send_close
 * @description div send close 처리
 * @returns {void}
 * @hidden N
 */
scwin.div_send_close = function () {
    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    if ($c.str.getByteLength(parentfm.split_redmpt_tp_cd.value) === 0) {
        parentfm.redmpt_methd_tp_cd[0].checked = true;
    } else {
        if (parentfm.split_redmpt_tp_cd.value === '1') {
            parentfm.redmpt_methd_tp_cd[1].checked = true;
        } else {
            if (parentfm.split_redmpt_tp_cd.value === '2') {
                parentfm.redmpt_methd_tp_cd[2].checked = true;
            } else {
                if (parentfm.split_redmpt_tp_cd.value === '3') {
                    parentfm.redmpt_methd_tp_cd[3].checked = true;
                }
            }
        }
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function () {
    const fm = (document.InputForm || { elements: [] });
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    let tr;
    let th;
    let td;
    const newRowNum = scwin.rownum + 1;
    const $tblNonEq = $('#tbl_non_eq');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td>" + newRowNum + "</td>").addClass('first txc');
    const $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"int_pay_dd_" + newRowNum + "\" name=\"int_pay_dd_" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'이자지급일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.int_pay_dd_" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.int_pay_dd_" + newRowNum + "')\" style=\"height: 24px;\" /></div></td>");
    const $td3 = $("<td><input type=\"text\" name=\"redmpt_amt_" + newRowNum + "\"  value=\'" + $c.util.getComponent('ipt_equivRedmptVal').getValue()+ "\' maxlength=18 class=\"txt short\" style=\"text-align: right;IME-MODE:disabled;width: 200px;border: none;\" onkeypress=\"NumberCheck(this)\" onFocus=\'Del_MoneyComma(this);\' onBlur=\'Add_MoneyComma(this);\' readonly=\'readonly\' /></td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tblNonEq.append($tr);
    scwin.rownum++;
    $("#int_pay_dd_" + newRowNum).datepicker(myDateOpts);
};

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRow = async function () {
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    if (scwin.rownum > 0) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        scwin.rownum--;
    } else {
        if (scwin.rownum < 1) {
            await $c.win.alert("삭제 할 행이 없습니다.");
        }
    }
};

// [A] 초기 목록 미해결 — jldbnf05008: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name autoCalcDone
 * @description auto Calc Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.autoCalcDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $(scwin.result.arrList).each(function(i, item) {
            if (i === 0) {
                $c.util.getComponent('cal_intPayDd1').setValue(item.day);
                $c.util.getComponent('ipt_redmptAmt1').setValue(item.val);
            } else {
                scwin.addRow();
                $("input[name='int_pay_dd_" + (i + 1) + "']").val(item.day);
                $("input[name='redmpt_amt_" + (i + 1) + "']").val(item.val);
            }
    });
};

/**
 * @method
 * @name autoCalc
 * @description auto Calc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.autoCalc = async function () {
    const r = await scwin.tx_fn_autoCalc();
    try {
        scwin.autoCalcDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf05008.fn_autoCalc' });
    }
    return r;
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
